<?php require 'config.php';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$s=$pdo->prepare('SELECT * FROM admins WHERE email=?');$s->execute([strtolower(trim($_POST['email']??''))]);$a=$s->fetch();if($a&&password_verify($_POST['password']??'',$a['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$a['id'];$_SESSION['admin_name']=$a['name'];go('admin_dashboard.php');}$err='Admin email or password incorrect.';} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Login</title><link rel="stylesheet" href="assets/style.css"></head><body class="auth"><form class="glass authbox" method="post"><div class="brand">◈ NML ICH <small>Administrator Access</small></div><h1>Admin Login</h1><p>Authorized administrators only.</p><?=flash()?><?=$err?'<div class="alert">'.e($err).'</div>':''?><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Admin email</label><input type="email" name="email" required><label>Password</label><input type="password" name="password" required><button>Sign in as Admin</button><p><a href="login.php">← Employee login</a></p></form></body></html>